import sys

# Increase recursion depth for deep BFS/DFS if necessary, 
# though we use an iterative approach here for efficiency.
sys.setrecursionlimit(2000000)

def solve():
    # Read H and W
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H = int(input_data[0])
    W = int(input_data[1])
    grid = input_data[2:]

    # Pre-calculate which cells are "frozen" (adjacent to a magnet)
    # A magnet cell itself is also blocked.
    is_frozen = [[False for _ in range(W)] for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == '#':
                is_frozen[r][c] = True
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        is_frozen[nr][nc] = True

    visited_main = [[False for _ in range(W)] for _ in range(H)]
    # last_seen_id is used to count reachable frozen cells for the current component
    # without resetting a whole 2D array every time.
    last_seen_id = [[-1 for _ in range(W)] for _ in range(H)]
    component_id = 0
    max_freedom = 0

    for r in range(H):
        for c in range(W):
            # Only start BFS from non-frozen, non-magnet empty cells
            if grid[r][c] == '.' and not is_frozen[r][c] and not visited_main[r][c]:
                component_id += 1
                stack = [(r, c)]
                visited_main[r][c] = True

                reachable_count = 0
                # Component contains free cells and boundary frozen cells
                free_cells_in_comp = 0
                frozen_cells_in_comp = 0

                comp_q = [(r, c)]
                while comp_q:
                    curr_r, curr_c = comp_q.pop()
                    free_cells_in_comp += 1

                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] == '#':
                                continue
                            if is_frozen[nr][nc]:
                                # If it's a frozen cell, we can reach it but not move further.
                                # Use component_id to ensure we only count it once for this BFS.
                                if last_seen_id[nr][nc] != component_id:
                                    last_seen_id[nr][nc] = component_id
                                    frozen_cells_in_comp += 1
                            else:
                                # If it's a free cell, continue BFS
                                if not visited_main[nr][nc]:
                                    visited_main[nr][nc] = True
                                    comp_q.append((nr, nc))

                max_freedom = max(max_freedom, free_cells_in_comp + frozen_cells_in_comp)

    # Special case: if every empty cell is frozen, the degree of freedom for any is 1.
    if max_freedom == 0:
        for r in range(H):
            for c in range(W):
                if grid[r][c] == '.':
                    max_freedom = 1
                    break

    print(max_freedom)

if __name__ == "__main__":
    solve()
```

