            coords = []
            for r in range(4):
                for c in range(4):
                    if current[r][c] == '#':
                        coords.append((r, c))
            rotations.append(coords)
            # Rotate 90 degrees clockwise
            next_grid = [['.' for _ in range(4)] for _ in range(4)]
            for r in range(4):
                for c in range(4):
                    next_grid[c][3-r] = current[r][c]
            current = ["".join(row) for row in next_grid]

        # Remove duplicate rotations (e.g. for symmetric pieces)
        unique_rots = []
        seen = set()
        for rot in rotations:
            # Sort to make a canonical tuple representation
            s_rot = tuple(sorted(rot))
            if s_rot not in seen:
                seen.add(s_rot)
                unique_rots.append(rot)
        return unique_rots

    # Pre-calculate all possible relative placements (rotations + translations)
    polys_variants = []
    total_hashes = 0
    for p in range(3):
        rots = get_rotations(raw_polys[p])
        variants = []
        for rot in rots:
            # Calculate total # for verification
            if p == 0: total_hashes += len(rot)
            elif p == 1: total_hashes += len(rot)
            elif p == 2: total_hashes += len(rot)

            # Find bounding box to determine translation limits
            min_r = min(r for r, c in rot)
            max_r = max(r for r, c in rot)
            min_c = min(c for r, c in rot)
            max_c = max(c for r, c in rot)

            height = max_r - min_r + 1
            width = max_c - min_c + 1

            for dr in range(-min_r, 4 - max_r):
                for dc in range(-min_c, 4 - max_c):
                    variant = set()
                    for r, c in rot:
                        variant.add((r + dr, c + dc))
                    variants.append(variant)
        polys_variants.append(variants)

    # If the sum of squares is not 16, they can't fill a 4x4 grid perfectly
    # (Checking one rotation of each is enough as length is constant)
    if sum(len(get_rotations(raw_polys[i])[0]) for i in range(3)) != 16:
        print("No")
