            combined12 = v1 | v2
            for v3 in polys_variants[2]:
                # Check overlap between (1+2) and 3
                if any(cell in combined12 for cell in v3):
                    continue
                # Since total hashes is 16 and no overlap, it covers 4x4
                print("Yes")
                return

