import sys

def solve():
    # Read all input data
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # Initialize distance matrix with infinity
    inf = float('inf')
    dist = [[inf] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        w = int(input_data[idx+2])
        dist[u][v] = min(dist[u][v], w)
        idx += 3

    # Floyd-Warshall to find all-pairs shortest paths
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dist[i][k] != inf and dist[k][j] != inf:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # DP for Traveling Salesperson Problem variant
    # dp[mask][i] is the min weight to visit subset 'mask' ending at vertex 'i'
    dp = [[inf] * N for _ in range(1 << N)]

    # Base case: Starting at any vertex i
    for i in range(N):
        dp[1 << i][i] = 0

    # Bitmask DP
    for mask in range(1, 1 << N):
        for u in range(N):
            if dp[mask][u] == inf:
                continue
            # Try to visit a vertex v not in the current mask
            for v in range(N):
                if not (mask & (1 << v)):
                    if dist[u][v] != inf:
                        new_mask = mask | (1 << v)
                        new_dist = dp[mask][u] + dist[u][v]
                        if dp[new_mask][v] > new_dist:
                            dp[new_mask][v] = new_dist

    # Find the minimum weight that covers all vertices
    ans = inf
    full_mask = (1 << N) - 1
    for i in range(N):
        ans = min(ans, dp[full_mask][i])

    if ans == inf:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
```

