def smallestString(s: str) -> str:
    s_list = list(s)
    n = len(s_list)

    # Find the first character that is not 'a'
    i = 0
    while i < n and s_list[i] == "a":
        i += 1

    # If all characters are 'a', we must change at least one character.
    # The best choice is to change the last 'a' to 'z'.
    if i == n:
        s_list[-1] = "z"
        return "".join(s_list)

    # Shift all non-'a' characters starting from index i
    while i < n and s_list[i] != "a":
        s_list[i] = chr(ord(s_list[i]) - 1)
        i += 1

    return "".join(s_list)
```

