def numberOfRightTriangles(grid: list[list[int]]) -> int:
    R = len(grid)
    C = len(grid[0])

    row_counts = [sum(row) for row in grid]
    col_counts = [sum(grid[r][c] for r in range(R)) for c in range(C)]

    ans = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 1:
                ans += (row_counts[r] - 1) * (col_counts[c] - 1)

    return ans
