class Solution:
    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        def count(n: int) -> int:
            s = str(n)
            memo = {}

            def dp(idx: int, is_less: bool, is_started: bool, diff: int, rem: int) -> int:
                if idx == len(s):
                    return 1 if is_started and diff == 0 and rem == 0 else 0

                state = (idx, is_less, is_started, diff, rem)
                if state in memo:
                    return memo[state]

                limit = 9 if is_less else int(s[idx])
                res = 0

                for digit in range(limit + 1):
                    new_is_less = is_less or (digit < limit)
                    if not is_started and digit == 0:
                        res += dp(idx + 1, new_is_less, False, diff, rem)
                    else:
                        new_diff = diff + (1 if digit % 2 == 0 else -1)
                        new_rem = (rem * 10 + digit) % k
                        res += dp(idx + 1, new_is_less, True, new_diff, new_rem)

                memo[state] = res
                return res

            return dp(0, False, False, 0, 0)

        return count(high) - count(low - 1)
```

