        for j in range(i, 0, -1):
            char = s[j - 1]
            counts[char] = counts.get(char, 0) + 1
            if counts[char] > max_freq:
                max_freq = counts[char]

            # The substring s[j-1:i] is balanced if its length equals
            # the number of distinct characters times the maximum frequency.
            if (i - j + 1) == len(counts) * max_freq:
                dp[i] = min(dp[i], dp[j - 1] + 1)

    return dp[n]
