def continuousSubarrays(nums: list[int]) -> int:
    min_deque = deque()
    max_deque = deque()
    left = 0
    total = 0

    for right, val in enumerate(nums):
        while min_deque and nums[min_deque[-1]] >= val:
            min_deque.pop()
        min_deque.append(right)

        while max_deque and nums[max_deque[-1]] <= val:
            max_deque.pop()
        max_deque.append(right)

        while nums[max_deque[0]] - nums[min_deque[0]] > 2:
            left += 1
            if min_deque[0] < left:
                min_deque.popleft()
            if max_deque[0] < left:
                max_deque.popleft()

        total += right - left + 1

    return total
