def stringIndices(wordsContainer: list[str], wordsQuery: list[str]) -> list[int]:
    # Root of the Trie
    # Each node will store:
    # - children: dict mapping char to Trie node
    # - best_idx: index of best word passing through or ending at this node
    trie = {}

    def get_better(idx1, idx2):
        if idx1 == -1:
            return idx2
        len1, len2 = len(wordsContainer[idx1]), len(wordsContainer[idx2])
        if len1 < len2:
            return idx1
        elif len2 < len1:
            return idx2
        return min(idx1, idx2)

    root_best = 0
    for i in range(1, len(wordsContainer)):
        root_best = get_better(root_best, i)

    # Node structure: {'best': idx, 'children': {}}
    root = {"best": root_best, "children": {}}

    for i, word in enumerate(wordsContainer):
        curr = root
        for ch in reversed(word):
            if ch not in curr["children"]:
                curr["children"][ch] = {"best": i, "children": {}}
            curr = curr["children"][ch]
            curr["best"] = get_better(curr["best"], i)

    ans = []
    for query in wordsQuery:
        curr = root
        best = curr["best"]
        for ch in reversed(query):
            if ch in curr["children"]:
                curr = curr["children"][ch]
                best = curr["best"]
            else:
                break
        ans.append(best)

    return ans
