import math


def findKthSmallest(coins: list[int], k: int) -> int:
    # Remove any coin that is a multiple of another coin to optimize PIE subsets
    coins = sorted(list(set(coins)))
    filtered_coins = []
    for c in coins:
        if not any(c % other == 0 for other in filtered_coins):
            filtered_coins.append(c)
    coins = filtered_coins

    n = len(coins)
    subsets = []
    for mask in range(1, 1 << n):
        lcm_val = 1
        bits = 0
        for i in range(n):
            if (mask >> i) & 1:
                bits += 1
                lcm_val = math.lcm(lcm_val, coins[i])
        sign = 1 if bits % 2 == 1 else -1
        subsets.append((lcm_val, sign))

    def count(m: int) -> int:
        return sum(sign * (m // lcm_val) for lcm_val, sign in subsets)

    low = 1
    high = min(coins) * k
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if count(mid) >= k:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return ans
