from itertools import permutations

def solve():
    # Read H and W
    line1 = sys.stdin.readline().split()
    if not line1:
        return
    H, W = map(int, line1)

    # Read Grid A
    A = []
    for _ in range(H):
        A.append(list(map(int, sys.stdin.readline().split())))

    # Read Grid B
    B = []
    for _ in range(H):
        B.append(list(map(int, sys.stdin.readline().split())))

    def count_inversions(p):
        inv = 0
        for i in range(len(p)):
            for j in range(i + 1, len(p)):
                if p[i] > p[j]:
                    inv += 1
        return inv

    min_ops = float('inf')
    found = False

    # Brute force all permutations of row indices and column indices
    # Since H, W <= 5, the search space is 5! * 5! = 120 * 120 = 14400
    row_perms = list(permutations(range(H)))
    col_perms = list(permutations(range(W)))

    for p_row in row_perms:
        for p_col in col_perms:
            match = True
            for i in range(H):
                for j in range(W):
                    if A[p_row[i]][p_col[j]] != B[i][j]:
                        match = False
                        break
                if not match:
                    break

            if match:
                found = True
                # The number of adjacent swaps to reach a permutation 
                # is equal to the number of inversions in that permutation.
                ops = count_inversions(p_row) + count_inversions(p_col)
                if ops < min_ops:
                    min_ops = ops

    if found:
        print(min_ops)
    else:
        print(-1)

