import sys

def solve():
    # Read all input data
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    # weight[i][j] stores weight of edge between vertex i and j
    # Using 0-indexing for vertices
    weights = [[0] * N for _ in range(N)]

    curr = 1
    for i in range(N - 1):
        for j in range(i + 1, N):
            w = int(input_data[curr])
            weights[i][j] = weights[j][i] = w
            curr += 1

    # dp[mask] = maximum weight for the set of vertices represented by the bitmask
    dp = [0] * (1 << N)

    for mask in range(1 << N):
        # Find the first vertex 'i' not in the matching for this mask
        i = -1
        for k in range(N):
            if not (mask & (1 << k)):
                i = k
                break

        if i == -1:
            continue

        # Option 1: Skip vertex 'i' and leave it unmatched
        next_mask_skip = mask | (1 << i)
        if dp[next_mask_skip] < dp[mask]:
            dp[next_mask_skip] = dp[mask]

        # Option 2: Match vertex 'i' with another available vertex 'j'
        for j in range(i + 1, N):
            if not (mask & (1 << j)):
                next_mask_match = mask | (1 << i) | (1 << j)
                new_weight = dp[mask] + weights[i][j]
                if dp[next_mask_match] < new_weight:
                    dp[next_mask_match] = new_weight

    print(dp[(1 << N) - 1])

