class Solution:
    def minOperationsToMakeMedianK(self, nums: list[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        m = n // 2

        operations = 0

        # Elements to the left of median (including median) must be <= k
        for i in range(m + 1):
            if nums[i] > k:
                operations += nums[i] - k

        # Elements to the right of median (including median) must be >= k
        for i in range(m, n):
            if nums[i] < k:
                operations += k - nums[i]

