def punishmentNumber(n: int) -> int:
    def can_partition(s: str, target: int) -> bool:
        if not s:
            return target == 0
        if target < 0:
            return False

        for i in range(1, len(s) + 1):
            val = int(s[:i])
            if val > target:
                break
            if can_partition(s[i:], target - val):
                return True
        return False

    total = 0
    for i in range(1, n + 1):
        sq = i * i
        if can_partition(str(sq), i):
            total += sq

    return total
