def minimumCost(source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
    # Initialize the distance matrix with infinity
    # There are 26 lowercase English letters
    dist = [[float('inf')] * 26 for _ in range(26)]

    # Distance from a character to itself is 0
    for i in range(26):
        dist[i][i] = 0

    # Populate the initial edges from the given transformations
    for u, v, w in zip(original, changed, cost):
        idx_u = ord(u) - ord('a')
        idx_v = ord(v) - ord('a')
        dist[idx_u][idx_v] = min(dist[idx_u][idx_v], w)

    # Use Floyd-Warshall algorithm to find all-pairs shortest paths
    for k in range(26):
        for i in range(26):
            if dist[i][k] == float('inf'):
                continue
            for j in range(26):
                if dist[k][j] < float('inf'):
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    total_cost = 0
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue

        c = dist[ord(s_char) - ord('a')][ord(t_char) - ord('a')]
        if c == float('inf'):
            return -1
        total_cost += c

    return int(total_cost)
