def countCompleteSubstrings(word: str, k: int) -> int:
    def count_valid(s: str) -> int:
        n = len(s)
        ans = 0
        # The number of unique characters can be from 1 to 26
        for m in range(1, 27):
            L = m * k
            if L > n:
                break

            freq = [0] * 26
            chars_with_k = 0
            unique_chars = 0

            for i in range(n):
                # Add s[i] to window
                idx = ord(s[i]) - ord('a')
                if freq[idx] == 0:
                    unique_chars += 1
                freq[idx] += 1
                if freq[idx] == k:
                    chars_with_k += 1
                elif freq[idx] == k + 1:
                    chars_with_k -= 1

                # Remove s[i - L] from window
                if i >= L:
                    idx_out = ord(s[i - L]) - ord('a')
                    if freq[idx_out] == k:
                        chars_with_k -= 1
                    elif freq[idx_out] == k + 1:
                        chars_with_k += 1
                    freq[idx_out] -= 1
                    if freq[idx_out] == 0:
                        unique_chars -= 1

                if i >= L - 1:
                    if chars_with_k == m and unique_chars == m:
                        ans += 1
        return ans

    total_complete = 0
    n = len(word)
    start = 0
    for i in range(n):
        if i > 0 and abs(ord(word[i]) - ord(word[i - 1])) > 2:
            total_complete += count_valid(word[start:i])
            start = i
    total_complete += count_valid(word[start:n])

    return total_complete
