def numberOfPowerfulInt(start: int, finish: int, limit: int, s: str) -> int:
    def count_powerful(n: int) -> int:
        n_str = str(n)
        if len(n_str) < len(s):
            return 0
        if len(n_str) == len(s):
            return 1 if int(s) <= n else 0

        prefix_len = len(n_str) - len(s)

        # Count powerful numbers strictly with fewer digits than n
        # Number of digits d from len(s) to len(n_str) - 1
        ans = 0
        for d in range(len(s), len(n_str)):
            pref_d = d - len(s)
            if pref_d == 0:
                ans += 1
            else:
                ans += min(limit, 9) * ((limit + 1) ** (pref_d - 1))

        # Count powerful numbers with the same number of digits as n
        # Digits available for prefix: 0 to limit, first digit 1 to limit
        # Check prefix matching
        for i in range(prefix_len):
            digit = int(n_str[i])
            min_digit = 1 if i == 0 else 0

            # If we choose a digit less than n_str[i]
            upper = min(digit - 1, limit)
            if upper >= min_digit:
                ans += (upper - min_digit + 1) * ((limit + 1) ** (prefix_len - 1 - i))

            # If current digit exceeds limit, we can't match further digits
            if digit > limit:
                break
        else:
            # All prefix digits match n_str's prefix
            # Check if suffix allows this number
            if n_str[prefix_len:] >= s:
                ans += 1

        return ans

    return count_powerful(finish) - count_powerful(start - 1)
