def maxSum(nums: list[int], m: int, k: int) -> int:
    counts = defaultdict(int)
    current_sum = 0
    max_sum = 0

    for i in range(len(nums)):
        current_sum += nums[i]
        counts[nums[i]] += 1

        if i >= k:
            left_elem = nums[i - k]
            current_sum -= left_elem
            counts[left_elem] -= 1
            if counts[left_elem] == 0:
                del counts[left_elem]

