def canTraverseAllPairs(nums: list[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True
    if 1 in nums:
        return False

    parent = list(range(n))

    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    max_val = max(nums)
    # Sieve to find the smallest prime factor (SPF) for each number up to max_val
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val**0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    prime_to_index = {}
    components = n

    for i, val in enumerate(nums):
        temp = val
        while temp > 1:
            p = spf[temp]
            if p in prime_to_index:
                if union(i, prime_to_index[p]):
                    components -= 1
            else:
                prime_to_index[p] = i
            while temp % p == 0:
                temp //= p

    return components == 1
```

