def lexicographicallySmallestArray(nums: list[int], limit: int) -> list[int]:
    n = len(nums)
    sorted_pairs = sorted((val, i) for i, val in enumerate(nums))

    result = [0] * n
    groups = []

    for val, i in sorted_pairs:
        if not groups or val - groups[-1][-1][0] > limit:
            groups.append([(val, i)])
        else:
            groups[-1].append((val, i))

