def specialPerm(nums: list[int]) -> int:
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute valid transitions
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                adj[i].append(j)

    # dp[mask][i] is the number of valid permutations of the subset `mask` ending with nums[i]
    dp = [[0] * n for _ in range(1 << n)]

    # Base cases: single element permutations
    for i in range(n):
        dp[1 << i][i] = 1

    # Fill DP table
    for mask in range(1 << n):
        for u in range(n):
            if not (mask & (1 << u)):
                continue
            if dp[mask][u] == 0:
                continue
            for v in adj[u]:
                if not (mask & (1 << v)):
                    next_mask = mask | (1 << v)
                    dp[next_mask][v] = (dp[next_mask][v] + dp[mask][u]) % MOD

    full_mask = (1 << n) - 1
    return sum(dp[full_mask]) % MOD
```

