class Solution:
    def maxPartitionsAfterOperations(self, s: str, k: k) -> int:
        from functools import lru_cache

        if k == 26:
            return 1

        n = len(s)

        @lru_cache(maxsize=None)
        def dp(index: int, current_mask: int, can_change: bool) -> int:
            if index == n:
                return 0

            char_bit = 1 << (ord(s[index]) - ord("a"))

            # Option 1: Do not change the current character
            new_mask = current_mask | char_bit
            if new_mask.bit_count() > k:
                ans = 1 + dp(index + 1, char_bit, can_change)
            else:
                ans = dp(index + 1, new_mask, can_change)

            # Option 2: Change the current character (if allowed)
            if can_change:
                for c in range(26):
                    c_bit = 1 << c
                    new_mask = current_mask | c_bit
                    if new_mask.bit_count() > k:
                        res = 1 + dp(index + 1, c_bit, False)
                    else:
                        res = dp(index + 1, new_mask, False)
                    if res > ans:
                        ans = res

            return ans

        return dp(0, 0, True) + 1
