import sys
import itertools

def solve():
    # Read input
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    r_str = input_data[1]
    c_str = input_data[2]

    # Possible symbols in each row/column
    symbols = ['A', 'B', 'C']

    # Generate all possible permutations of a row of length N
    # containing exactly one 'A', one 'B', one 'C', and N-3 '.'
    row_elements = symbols + ['.'] * (n - 3)
    all_perms = sorted(list(set(itertools.permutations(row_elements))))

    grid = [None] * n

    def check_col_constraints(current_n):
        # Check column constraints for the first 'current_n' rows
        for j in range(n):
            col_chars = [grid[i][j] for i in range(current_n) if grid[i][j] != '.']

            # Check for duplicates in columns
            if len(col_chars) != len(set(col_chars)):
                return False

            # If column is finished (current_n == n), check if it has exactly A, B, C
            if current_n == n:
                if sorted(col_chars) != ['A', 'B', 'C']:
                    return False

            # Check Topmost constraint
            if col_chars:
                if col_chars[0] != c_str[j]:
                    return False
        return True

    def backtrack(row_idx):
        if row_idx == n:
            if check_col_constraints(n):
                print("Yes")
                for r in grid:
                    print("".join(r))
                return True
            return False

        for perm in all_perms:
            # Check Leftmost constraint for the row
            leftmost = next((char for char in perm if char != '.'), None)
            if leftmost != r_str[row_idx]:
                continue

            grid[row_idx] = perm

            # Pruning: Check column duplicates and Topmost constraint
            possible = True
            for j in range(n):
                col_chars = [grid[i][j] for i in range(row_idx + 1) if grid[i][j] != '.']
                if len(col_chars) != len(set(col_chars)):
                    possible = False
                    break
                if col_chars and col_chars[0] != c_str[j]:
                    possible = False
                    break

            if possible:
                if backtrack(row_idx + 1):
                    return True
        return False

    if not backtrack(0):
        print("No")

if __name__ == "__main__":
