def findMinimumOperations(s1: str, s2: str, s3: str) -> int:
    min_len = min(len(s1), len(s2), len(s3))
    common_prefix_len = 0

    while common_prefix_len < min_len and s1[common_prefix_len] == s2[common_prefix_len] == s3[common_prefix_len]:
        common_prefix_len += 1

    if common_prefix_len == 0:
        return -1

    return (len(s1) - common_prefix_len) + (len(s2) - common_prefix_len) + (len(s3) - common_prefix_len)
