def maximumSubarraySum(nums: list[int], k: int) -> int:
    min_prefix = {}
    prefix_sum = 0
    max_sum = float("-inf")

    for x in nums:
        # Check if x - k has appeared as a start
        if x - k in min_prefix:
            max_sum = max(max_sum, prefix_sum + x - min_prefix[x - k])
        # Check if x + k has appeared as a start
        if x + k in min_prefix:
            max_sum = max(max_sum, prefix_sum + x - min_prefix[x + k])

        # We can also start a subarray with x.
        # The sum before including x is prefix_sum.
        if x not in min_prefix or prefix_sum < min_prefix[x]:
            min_prefix[x] = prefix_sum

        prefix_sum += x

    return max_sum if max_sum != float("-inf") else 0
